//! The Craft Apps' alternate icon packs: which exist, and where their artwork is.
//!
//! A pack is a folder of `<app>.svg` files under `assets/app-icons/alternate_icons/`, named by one
//! row in that folder's `packs.tsv`. The folder is the pack's **id** — what a saved choice stores,
//! so renaming one after a release sends a saved choice back to `Default` — and its row's English
//! text is the **label** the UI shows and translates.
//!
//! The tables below are generated by `crates/core/build.rs`, which reads those folders and fails
//! the build when they and `packs.tsv` disagree. Adding a pack is therefore a matter of adding
//! files; see `assets/app-icons/alternate_icons/README.md`.

include!(concat!(env!("OUT_DIR"), "/icon_packs.rs"));

/// One bundled icon pack.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct IconPack {
    /// The folder under `assets/app-icons/alternate_icons/`, which is also the pack's id.
    pub id: &'static str,
    /// The English label shown in Settings → App icons, translated by the UI like any other
    /// string. Every catalog that claims to be complete needs a row for it.
    pub label: &'static str,
}

/// The bundled artwork for one app in one pack.
pub struct Artwork {
    /// The 512 px render `packaging/icons.sh` wrote. Every platform derives the sizes it asks for
    /// from this one: the icon theme's fixed folders, a Windows `.ico`, a macOS `NSImage`.
    pub png: &'static [u8],
    /// The supplied SVG, for the icon themes' `scalable` folders.
    pub svg: &'static str,
}

/// Every pack, in the order `packs.tsv` lists them — the order the launcher offers them in.
pub fn packs() -> impl Iterator<Item = &'static IconPack> {
    PACKS.iter()
}

/// The pack with this id, or `None` for one this build doesn't have.
pub fn pack(id: &str) -> Option<&'static IconPack> {
    PACKS.iter().find(|p| p.id == id)
}

/// The artwork of `app` in the pack `id`, or `None` where that pack wasn't drawn for it.
pub fn artwork(app: &str, id: &str) -> Option<Artwork> {
    let (_, _, png, svg) = ARTWORK.iter().find(|(pack, drawn_for, _, _)| *pack == id && *drawn_for == app)?;
    Some(Artwork { png, svg })
}

/// The packs `app` was drawn for, in the order the launcher offers them.
pub fn packs_for(app: &str) -> impl Iterator<Item = &'static IconPack> + '_ {
    PACKS.iter().filter(move |p| artwork(app, p.id).is_some())
}

/// Whether the pack `id` was drawn for `app`.
pub fn has_artwork(app: &str, id: &str) -> bool {
    artwork(app, id).is_some()
}

/// Whether any pack holds artwork for `app`.
pub fn has_packs(app: &str) -> bool {
    ARTWORK.iter().any(|(_, drawn_for, _, _)| *drawn_for == app)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{CraftApp, SUITE};

    #[test]
    fn every_pack_is_listed_once_and_its_artwork_is_whole() {
        assert!(!PACKS.is_empty());
        let mut ids = std::collections::BTreeSet::new();
        let mut labels = std::collections::BTreeSet::new();
        for pack in PACKS {
            assert!(ids.insert(pack.id), "{} is listed twice", pack.id);
            assert!(labels.insert(pack.label), "{} is used by two packs", pack.label);
            assert!(!pack.label.is_empty(), "{} has no label", pack.id);
            assert!(packs_for("photocraft").any(|p| p.id == pack.id), "{} holds no artwork for PhotoCraft", pack.id);
            for app in &SUITE {
                let Some(art) = artwork(app.id, pack.id) else { continue };
                assert!(art.svg.contains("<svg"), "{} {}: the SVG isn't one", pack.id, app.id);
                assert_eq!(png_size(art.png), (512, 512), "{} {}: the master render", pack.id, app.id);
            }
        }
        assert!(pack("no-such-pack").is_none());
    }

    /// A file named after something that isn't an app would be bundled for nothing, while the app
    /// it was meant for silently keeps its own icon. Easy to typo when adding several at once, and
    /// invisible otherwise, so it fails here.
    #[test]
    fn every_artwork_file_is_named_after_a_real_app() {
        for (pack, app, _, _) in ARTWORK {
            assert!(CraftApp::by_id(app).is_some(), "{pack}/{app}.svg: `{app}` isn't a Craft App id");
        }
    }

    /// A PNG's size, read from its IHDR, so `core` needs no image crate.
    fn png_size(png: &[u8]) -> (u32, u32) {
        let field = |at: usize| png.get(at..at + 4).and_then(|b| b.try_into().ok()).map(u32::from_be_bytes).unwrap_or(0);
        (field(16), field(20))
    }

    #[test]
    fn a_pack_answers_only_for_the_apps_it_was_drawn_for() {
        for app in &SUITE {
            assert_eq!(app.has_alternate_icons(), has_packs(app.id), "{}", app.id);
            for style in crate::IconStyle::all() {
                let drawn_for = style.pack().is_none_or(|id| artwork(app.id, id).is_some());
                assert_eq!(app.supports_icon_style(style), drawn_for, "{} {style:?}", app.id);
            }
            // An app offers exactly the packs that hold artwork for it — no more, no fewer. Adding
            // artwork for an app is all it takes for the picker to offer it; nothing is listed in
            // Rust by hand, so this holds for every app however many packs there are.
            let offered: Vec<&str> = app.icon_styles().filter_map(|s| s.pack()).collect();
            let drawn_for: Vec<&str> = PACKS.iter().filter(|p| artwork(app.id, p.id).is_some()).map(|p| p.id).collect();
            assert_eq!(offered, drawn_for, "{}", app.id);
        }
    }
}
